//! Filesystem module for CipherBox Desktop.
//!
//! Mounts the encrypted vault at ~/CipherBox as a native filesystem.
//! On macOS: FUSE-T (fuser crate). On Windows: WinFsp (winfsp crate).
//! All crypto operations happen in Rust via the crypto module.
//!
//! The cache, inode, and file_handle modules are always available (platform-agnostic).
//! The operations module requires the `fuse` feature (macOS) or `winfsp` feature (Windows).

pub mod cache;
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub(crate) mod constants;
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub mod decrypt;
pub mod file_handle;
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub(crate) mod helpers;
pub mod inode;
#[cfg(feature = "fuse")]
mod read_ops;
#[cfg(feature = "fuse")]
mod write_ops;
#[cfg(feature = "fuse")]
mod dir_ops;
#[cfg(feature = "fuse")]
pub mod operations;
#[cfg(feature = "winfsp")]
pub mod windows;

// Re-export Windows mount/unmount so callers can use crate::fuse::mount_filesystem
// with the same function name regardless of platform (only one feature active per build).
#[cfg(feature = "winfsp")]
pub use windows::mount_filesystem;
#[cfg(feature = "winfsp")]
pub use windows::unmount_filesystem;

#[cfg(any(feature = "fuse", feature = "winfsp"))]
use std::collections::HashMap;
#[cfg(any(feature = "fuse", feature = "winfsp"))]
use std::path::PathBuf;
#[cfg(any(feature = "fuse", feature = "winfsp"))]
use std::sync::atomic::AtomicU64;
#[cfg(any(feature = "fuse", feature = "winfsp"))]
use std::sync::Arc;
#[cfg(any(feature = "fuse", feature = "winfsp"))]
use zeroize::{Zeroize, Zeroizing};

#[cfg(any(feature = "fuse", feature = "winfsp"))]
use std::time::Duration;

#[cfg(feature = "fuse")]
use fuser::MountOption;

#[cfg(any(feature = "fuse", feature = "winfsp"))]
use crate::api::client::ApiClient;
#[cfg(any(feature = "fuse", feature = "winfsp"))]
use crate::state::AppState;

/// Timeout for network I/O in filesystem callbacks to prevent blocking the mount thread.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
const NETWORK_TIMEOUT: Duration = Duration::from_secs(10);

/// Run an async future with a timeout on the tokio runtime.
/// Prevents filesystem thread hangs from indefinite network I/O.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
fn block_with_timeout<F, T>(rt: &tokio::runtime::Handle, fut: F) -> Result<T, String>
where
    F: std::future::Future<Output = Result<T, String>>,
{
    rt.block_on(async {
        match tokio::time::timeout(NETWORK_TIMEOUT, fut).await {
            Ok(result) => result,
            Err(_) => Err("Operation timed out".to_string()),
        }
    })
}

/// Pending folder refresh result sent from background tasks.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub struct PendingRefresh {
    pub ino: u64,
    pub ipns_name: String,
    pub metadata: crate::crypto::folder::FolderMetadata,
    pub cid: String,
}

/// Pending content prefetch result sent from background tasks.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub enum PendingContent {
    Success { cid: String, data: Vec<u8> },
    Failure { cid: String },
}

/// Notification from a background upload thread that a file upload completed.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub struct UploadComplete {
    pub ino: u64,
    pub new_cid: String,
    pub parent_ino: u64,
    pub old_file_cid: Option<String>,
    /// CIDs of pruned versions (exceeded MAX_VERSIONS_PER_FILE) to unpin.
    pub pruned_cids: Vec<String>,
    /// Write generation at the time this upload was started.
    /// Used to skip stale uploads from previous open/write/release cycles.
    pub write_generation: u64,
}

/// Entry in the debounced publish queue.
/// Tracks folders that need metadata published after file mutations.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
struct PublishQueueEntry {
    /// When the first mutation was queued (for debounce timing).
    first_dirty: std::time::Instant,
    /// Number of file uploads still in flight for this folder.
    pending_uploads: usize,
}

/// Coordinates IPNS publish operations to prevent sequence number races
/// and maintain a monotonic sequence number cache per IPNS name.
///
/// Shared via `Arc` between `CipherBoxFS` and background publish threads.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub struct PublishCoordinator {
    /// Per-IPNS-name sequence number cache (monotonically increasing).
    seq_cache: std::sync::Mutex<HashMap<String, u64>>,
    /// Per-IPNS-name publish locks to serialize concurrent publishes.
    publish_locks: std::sync::Mutex<HashMap<String, Arc<tokio::sync::Mutex<()>>>>,
}

#[cfg(any(feature = "fuse", feature = "winfsp"))]
impl PublishCoordinator {
    pub fn new() -> Self {
        Self {
            seq_cache: std::sync::Mutex::new(HashMap::new()),
            publish_locks: std::sync::Mutex::new(HashMap::new()),
        }
    }

    /// Get or create a per-folder publish lock.
    pub fn get_lock(&self, ipns_name: &str) -> Arc<tokio::sync::Mutex<()>> {
        let mut locks = self.publish_locks.lock().unwrap();
        locks
            .entry(ipns_name.to_string())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone()
    }

    /// Resolve current sequence number with monotonic cache fallback.
    ///
    /// - On successful resolve: returns max(resolved, cached)
    /// - On failed resolve with cached value: returns cached value with warning
    /// - On failed resolve with no cache: returns error (prevents seq rollback)
    pub async fn resolve_sequence(
        &self,
        api: &crate::api::client::ApiClient,
        ipns_name: &str,
    ) -> Result<u64, String> {
        match crate::api::ipns::resolve_ipns(api, ipns_name).await {
            Ok(resp) => {
                let resolved = match resp.sequence_number.parse::<u64>() {
                    Ok(v) => v,
                    Err(e) => {
                        log::warn!(
                            "Failed to parse IPNS sequence '{}' for {}: {}",
                            resp.sequence_number, ipns_name, e
                        );
                        0
                    }
                };
                let cached = self.get_cached(ipns_name).unwrap_or(0);
                let seq = std::cmp::max(resolved, cached);
                self.update_cache(ipns_name, seq);
                Ok(seq)
            }
            Err(e) => match self.get_cached(ipns_name) {
                Some(cached) => {
                    log::warn!(
                        "IPNS resolve failed for {}, using cached seq {}: {}",
                        ipns_name,
                        cached,
                        e
                    );
                    Ok(cached)
                }
                None => Err(format!(
                    "IPNS resolve failed and no cached sequence for {}: {}",
                    ipns_name, e
                )),
            },
        }
    }

    /// Record a successful publish — cache is monotonic (only increases).
    pub fn record_publish(&self, ipns_name: &str, published_seq: u64) {
        self.update_cache(ipns_name, published_seq);
    }

    fn get_cached(&self, ipns_name: &str) -> Option<u64> {
        self.seq_cache.lock().unwrap().get(ipns_name).copied()
    }

    fn update_cache(&self, ipns_name: &str, seq: u64) {
        let mut cache = self.seq_cache.lock().unwrap();
        let entry = cache.entry(ipns_name.to_string()).or_insert(0);
        if seq > *entry {
            *entry = seq;
        }
    }
}

/// Encrypt a FolderMetadata struct and package as JSON bytes ready for IPFS upload.
/// CPU-only, no network I/O.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
fn encrypt_metadata_to_json(
    metadata: &crate::crypto::folder::FolderMetadata,
    folder_key: &[u8],
) -> Result<Vec<u8>, String> {
    let folder_key_arr: [u8; 32] = folder_key
        .try_into()
        .map_err(|_| "Invalid folder key length".to_string())?;
    let sealed = crate::crypto::folder::encrypt_folder_metadata(metadata, &folder_key_arr)
        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
    let iv_hex = hex::encode(&sealed[..12]);
    use base64::Engine;
    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
    let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
    serde_json::to_vec(&json).map_err(|e| format!("JSON serialization failed: {}", e))
}

/// Merge local children onto remote children to resolve a concurrent-edit conflict.
///
/// Strategy (last-writer-wins per child, additive merge):
/// - Start with remote children as base
/// - For each child also present locally (by IPNS name): use local version (handles rename)
/// - For each child present locally but NOT in remote: add it (new file/folder from this device)
/// - For each child present in remote but NOT locally: preserve remote (without tombstones we
///   cannot distinguish "local deleted it" from "local never saw it", so we err on the side of
///   preserving data to avoid dropping concurrent additions)
///
/// This is a purely additive merge -- no deletions are performed.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
fn merge_folder_children(
    local: &crate::crypto::folder::FolderMetadata,
    remote: crate::crypto::folder::FolderMetadata,
) -> crate::crypto::folder::FolderMetadata {
    use crate::crypto::folder::FolderChild;

    /// Extract the stable IPNS identifier for a child entry.
    fn child_ipns_key(child: &FolderChild) -> &str {
        match child {
            FolderChild::Folder(f) => f.ipns_name.as_str(),
            FolderChild::File(f) => f.file_meta_ipns_name.as_str(),
        }
    }

    // Build lookup map keyed by IPNS name for local children.
    let local_by_ipns: std::collections::HashMap<String, &FolderChild> = local
        .children
        .iter()
        .map(|c| (child_ipns_key(c).to_string(), c))
        .collect();

    let mut merged: Vec<FolderChild> = Vec::new();
    let mut seen_ipns: std::collections::HashSet<String> = std::collections::HashSet::new();

    // Walk remote children in original order (deterministic iteration).
    // If local has a version of this child, use local (handles rename/modify).
    // Otherwise, preserve the remote child -- without tombstones we cannot
    // distinguish "local deleted it" from "local never saw it", so we err on
    // the side of preserving data to avoid dropping concurrent additions.
    for remote_child in &remote.children {
        let ipns = child_ipns_key(remote_child).to_string();
        if let Some(local_child) = local_by_ipns.get(&ipns) {
            merged.push((*local_child).clone());
        } else {
            // Preserve remote child to avoid dropping concurrent additions.
            merged.push(remote_child.clone());
        }
        seen_ipns.insert(ipns);
    }

    // Add any locally-added children that don't exist in remote (new files/folders).
    for local_child in &local.children {
        let ipns = child_ipns_key(local_child).to_string();
        if !seen_ipns.contains(&ipns) {
            merged.push(local_child.clone());
        }
    }

    crate::crypto::folder::FolderMetadata {
        version: "v2".to_string(),
        children: merged,
    }
}

/// Spawn a background OS thread to upload encrypted metadata and publish via IPNS.
/// Returns immediately — does NOT block the calling thread.
///
/// On 409 Conflict (another device published since our last sync):
/// 1. Re-fetches remote metadata via IPNS resolve + IPFS fetch + decrypt
/// 2. Merges local changes onto remote children (additive, preserves other devices' changes)
/// 3. Adds jitter to break symmetry with other concurrent devices
/// 4. Re-encrypts merged metadata and retries once with fresh sequence
/// 5. On persistent conflict (retry also 409): logs error, does not retry again
#[cfg(any(feature = "fuse", feature = "winfsp"))]
fn spawn_metadata_publish(
    api: Arc<ApiClient>,
    rt: tokio::runtime::Handle,
    metadata: crate::crypto::folder::FolderMetadata,
    folder_key: Vec<u8>,
    ipns_private_key: Vec<u8>,
    ipns_name: String,
    old_metadata_cid: Option<String>,
    coordinator: Arc<PublishCoordinator>,
) {
    std::thread::spawn(move || {
        let result = rt.block_on(async {
            // Acquire per-folder publish lock to serialize concurrent publishes
            let lock = coordinator.get_lock(&ipns_name);
            let _guard = lock.lock().await;

            // Encrypt metadata (CPU)
            let json_bytes = encrypt_metadata_to_json(&metadata, &folder_key)?;

            // Resolve current IPNS sequence number (monotonic cache fallback)
            let seq = coordinator.resolve_sequence(&api, &ipns_name).await?;

            // Upload encrypted metadata to IPFS
            let new_cid = crate::api::ipfs::upload_content(&api, &json_bytes).await?;

            // Create and sign IPNS record
            let ipns_key_arr: [u8; 32] = ipns_private_key
                .try_into()
                .map_err(|_| "Invalid IPNS private key length".to_string())?;
            let new_seq = seq + 1;
            let value = format!("/ipfs/{}", new_cid);
            let record = crate::crypto::ipns::create_ipns_record(
                &ipns_key_arr,
                &value,
                new_seq,
                86_400_000,
            )
            .map_err(|e| format!("IPNS record creation failed: {}", e))?;
            let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
                .map_err(|e| format!("IPNS record marshal failed: {}", e))?;

            use base64::Engine;
            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);

            let req = crate::api::ipns::IpnsPublishRequest {
                ipns_name: ipns_name.clone(),
                record: record_b64,
                metadata_cid: new_cid.clone(),
                encrypted_ipns_private_key: None,
                key_epoch: None,
                expected_sequence_number: Some(seq.to_string()),
            };

            match crate::api::ipns::publish_ipns(&api, &req).await? {
                crate::api::ipns::PublishResult::Success => {
                    // Publish succeeded on first attempt
                    coordinator.record_publish(&ipns_name, new_seq);

                    // Unpin old metadata CID
                    if let Some(old) = old_metadata_cid {
                        let _ = crate::api::ipfs::unpin_content(&api, &old).await;
                    }

                    log::info!("Background metadata publish succeeded for {}", ipns_name);
                }

                crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
                    // Another device published since our last sync.
                    // Re-fetch remote state, merge local changes, and retry once.
                    log::warn!(
                        "Conflict detected for {}: expected seq {}, server has {}. Re-syncing...",
                        ipns_name, seq, current_sequence_number
                    );

                    // 1. Re-resolve the sequence number from the server (fresh, authoritative)
                    let fresh_seq = coordinator.resolve_sequence(&api, &ipns_name).await?;

                    // 2. Resolve the IPNS name to get the remote CID
                    let remote_resolve = crate::api::ipns::resolve_ipns(&api, &ipns_name).await?;
                    let remote_cid = remote_resolve.cid;

                    // 3. Fetch and decrypt the remote metadata (contains the other device's changes)
                    let remote_bytes = crate::api::ipfs::fetch_content(&api, &remote_cid).await?;
                    let remote_metadata = crate::fuse::decrypt::decrypt_metadata_from_ipfs_public(
                        &remote_bytes, &folder_key,
                    )?;

                    // 4. Merge: apply local mutation onto remote children.
                    //    Preserves both this device's changes AND the other device's changes.
                    let merged_metadata = merge_folder_children(&metadata, remote_metadata);

                    // 5. Small random jitter to break symmetry with other concurrent devices
                    let jitter_ms = (std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .subsec_nanos() % 400) as u64 + 100;
                    tokio::time::sleep(std::time::Duration::from_millis(jitter_ms)).await;

                    // 6. Re-encrypt the MERGED metadata and upload
                    let retry_json = encrypt_metadata_to_json(&merged_metadata, &folder_key)?;
                    let retry_cid = crate::api::ipfs::upload_content(&api, &retry_json).await?;

                    // 7. Create new IPNS record with fresh sequence
                    let retry_seq = fresh_seq + 1;
                    let retry_value = format!("/ipfs/{}", retry_cid);
                    let retry_record = crate::crypto::ipns::create_ipns_record(
                        &ipns_key_arr, &retry_value, retry_seq, 86_400_000,
                    ).map_err(|e| format!("IPNS retry record creation failed: {}", e))?;
                    let retry_marshaled = crate::crypto::ipns::marshal_ipns_record(&retry_record)
                        .map_err(|e| format!("IPNS retry record marshal failed: {}", e))?;
                    let retry_b64 = base64::engine::general_purpose::STANDARD.encode(&retry_marshaled);

                    let retry_cid_for_cleanup = retry_cid.clone();
                    let retry_req = crate::api::ipns::IpnsPublishRequest {
                        ipns_name: ipns_name.clone(),
                        record: retry_b64,
                        metadata_cid: retry_cid,
                        encrypted_ipns_private_key: None,
                        key_epoch: None,
                        expected_sequence_number: Some(fresh_seq.to_string()),
                    };

                    match crate::api::ipns::publish_ipns(&api, &retry_req).await? {
                        crate::api::ipns::PublishResult::Success => {
                            coordinator.record_publish(&ipns_name, retry_seq);

                            // Unpin orphaned CID from first failed attempt
                            let _ = crate::api::ipfs::unpin_content(&api, &new_cid).await;
                            // Unpin old metadata CID (same as success path)
                            if let Some(old) = old_metadata_cid {
                                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
                            }

                            log::info!(
                                "Conflict resolved for {} after retry (seq {})",
                                ipns_name, retry_seq
                            );
                        }
                        crate::api::ipns::PublishResult::Conflict { .. } => {
                            // Persistent conflict after single retry -- do not loop.
                            // User should wait for automatic resync on next polling cycle.
                            // Best-effort cleanup of orphaned CIDs from both attempts.
                            let _ = crate::api::ipfs::unpin_content(&api, &new_cid).await;
                            let _ = crate::api::ipfs::unpin_content(&api, &retry_cid_for_cleanup).await;

                            log::error!(
                                "Persistent conflict for {} after retry. \
                                Another device is actively modifying this folder. \
                                Changes will resync on next polling cycle.",
                                ipns_name
                            );
                            return Err(format!(
                                "Persistent conflict for {}. Another device is actively modifying this folder.",
                                ipns_name
                            ));
                        }
                    }
                }
            }

            Ok::<(), String>(())
        });

        if let Err(e) = result {
            log::error!("Background metadata publish failed: {}", e);
        }
    });
}

/// Add a BinEntry to the user's encrypted recycle bin IPNS record.
///
/// Background operation: reads existing bin metadata from IPNS (or creates empty),
/// appends the new entry, encrypts with ECIES, uploads to IPFS, publishes IPNS.
/// Fire-and-forget -- errors are logged but don't propagate.
/// CIDs remain pinned on delete for recovery via the web app bin UI.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub(crate) fn spawn_bin_entry_publish(
    api: Arc<ApiClient>,
    rt: tokio::runtime::Handle,
    entry: crate::crypto::bin::BinEntry,
    user_private_key: Vec<u8>,
    user_public_key: Vec<u8>,
    coordinator: Arc<PublishCoordinator>,
) {
    std::thread::spawn(move || {
        let result = rt.block_on(async {
            // 1. Derive the bin IPNS keypair from user's private key
            let pk_arr: [u8; 32] = user_private_key.clone().try_into()
                .map_err(|_| "Invalid private key length for bin derivation".to_string())?;
            let (bin_ipns_private_key, _bin_ipns_public_key, bin_ipns_name) =
                crate::crypto::hkdf::derive_bin_ipns_keypair(&pk_arr)
                    .map_err(|e| format!("Bin IPNS derivation failed: {}", e))?;

            // 2. Acquire per-IPNS publish lock
            let lock = coordinator.get_lock(&bin_ipns_name);
            let _guard = lock.lock().await;

            // 3. Try to resolve existing bin metadata from IPNS
            let (mut bin_metadata, existing_cid) = match crate::api::ipns::resolve_ipns(&api, &bin_ipns_name).await {
                Ok(resp) => {
                    // Fetch and decrypt existing bin metadata
                    match crate::api::ipfs::fetch_content(&api, &resp.cid).await {
                        Ok(bytes) => {
                            match crate::crypto::bin::decrypt_bin_metadata(&bytes, &user_private_key) {
                                Ok(meta) => (meta, Some(resp.cid)),
                                Err(e) => {
                                    log::warn!("Failed to decrypt existing bin metadata, starting fresh: {}", e);
                                    (crate::crypto::bin::empty_bin_metadata(), None)
                                }
                            }
                        }
                        Err(e) => {
                            log::warn!("Failed to fetch bin metadata blob, starting fresh: {}", e);
                            (crate::crypto::bin::empty_bin_metadata(), None)
                        }
                    }
                }
                Err(_) => {
                    // No existing bin IPNS record -- first time using bin
                    (crate::crypto::bin::empty_bin_metadata(), None)
                }
            };

            // 4. Add the new entry and increment sequence number
            bin_metadata.sequence_number += 1;
            bin_metadata.entries.push(entry);

            // 5. Encrypt with ECIES using user's public key
            let encrypted = crate::crypto::bin::encrypt_bin_metadata(&bin_metadata, &user_public_key)
                .map_err(|e| format!("Bin metadata encryption failed: {}", e))?;

            // 6. Upload to IPFS
            let new_cid = crate::api::ipfs::upload_content(&api, &encrypted).await?;

            // 7. Resolve current IPNS sequence and publish
            let seq = coordinator.resolve_sequence(&api, &bin_ipns_name).await.unwrap_or(0);
            let new_seq = seq + 1;

            let bin_ipns_key_arr: [u8; 32] = bin_ipns_private_key.as_slice().try_into()
                .map_err(|_| "Invalid bin IPNS key length".to_string())?;
            let value = format!("/ipfs/{}", new_cid);
            let record = crate::crypto::ipns::create_ipns_record(
                &bin_ipns_key_arr, &value, new_seq, 86_400_000,
            ).map_err(|e| format!("Bin IPNS record creation failed: {}", e))?;
            let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
                .map_err(|e| format!("Bin IPNS marshal failed: {}", e))?;

            use base64::Engine;
            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);

            let req = crate::api::ipns::IpnsPublishRequest {
                ipns_name: bin_ipns_name.clone(),
                record: record_b64,
                metadata_cid: new_cid,
                encrypted_ipns_private_key: None,
                key_epoch: None,
                expected_sequence_number: Some(seq.to_string()),
            };

            match crate::api::ipns::publish_ipns(&api, &req).await? {
                crate::api::ipns::PublishResult::Success => {
                    coordinator.record_publish(&bin_ipns_name, new_seq);
                    // Unpin old bin metadata CID
                    if let Some(old) = existing_cid {
                        let _ = crate::api::ipfs::unpin_content(&api, &old).await;
                    }
                    log::info!("Bin entry published for '{}'", bin_metadata.entries.last().map(|e| e.name.as_str()).unwrap_or("?"));
                }
                crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
                    // On conflict, log warning. The entry will be lost for this delete,
                    // but the CID stays pinned (no data loss). Next delete or web app
                    // session will create a fresh bin state.
                    log::warn!(
                        "Bin IPNS publish conflict (expected {}, server {}). Bin entry not saved, but CID preserved.",
                        seq, current_sequence_number
                    );
                }
            }

            Ok::<(), String>(())
        });

        if let Err(e) = result {
            log::error!("Background bin entry publish failed: {}", e);
        }
    });
}

/// The main filesystem struct.
///
/// Shared between macOS FUSE and Windows WinFsp implementations.
/// Contains the inode table, caches, API client, and all state needed
/// for filesystem operations.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub struct CipherBoxFS {
    /// Inode table mapping inode numbers to metadata.
    pub inodes: inode::InodeTable,
    /// Folder metadata cache with 30s TTL.
    pub metadata_cache: cache::MetadataCache,
    /// File content cache with 256 MiB LRU eviction.
    pub content_cache: cache::ContentCache,
    /// API client for IPFS/IPNS operations.
    pub api: Arc<ApiClient>,
    /// User's secp256k1 private key for ECIES decryption (32 bytes).
    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
    pub private_key: Zeroizing<Vec<u8>>,
    /// User's uncompressed secp256k1 public key (65 bytes, 0x04 prefix).
    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
    pub public_key: Zeroizing<Vec<u8>>,
    /// Root folder AES-256 key (32 bytes).
    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
    pub root_folder_key: Zeroizing<Vec<u8>>,
    /// Root IPNS name (k51... format).
    pub root_ipns_name: String,
    /// Tokio runtime handle for spawning async tasks from filesystem threads.
    pub rt: tokio::runtime::Handle,
    /// Next file handle counter.
    pub next_fh: AtomicU64,
    /// Map of open file handles (file_handle::OpenFileHandle for write buffering).
    pub open_files: HashMap<u64, file_handle::OpenFileHandle>,
    /// Temp directory for write-buffered files.
    pub temp_dir: PathBuf,
    /// TEE public key hex for encrypting IPNS private keys on new folder creation.
    pub tee_public_key: Option<Vec<u8>>,
    /// TEE key epoch for encrypting IPNS private keys on new folder creation.
    pub tee_key_epoch: Option<u32>,
    /// Receiver for background refresh results.
    pub refresh_rx: std::sync::mpsc::Receiver<PendingRefresh>,
    /// Sender clone for spawning background refreshes.
    pub refresh_tx: std::sync::mpsc::Sender<PendingRefresh>,
    /// Folders with recent local mutations — skip background refreshes
    /// that would overwrite local state before IPNS publish propagates.
    /// Maps folder ino -> mutation timestamp.
    pub mutated_folders: HashMap<u64, std::time::Instant>,
    /// CIDs currently being prefetched in background (to avoid duplicate fetches).
    pub prefetching: std::collections::HashSet<String>,
    /// Receiver for background content prefetch results.
    pub content_rx: std::sync::mpsc::Receiver<PendingContent>,
    /// Sender for background content prefetch tasks.
    pub content_tx: std::sync::mpsc::Sender<PendingContent>,
    /// Plaintext cache for files whose upload is still in flight (keyed by inode).
    pub pending_content: HashMap<u64, Vec<u8>>,
    /// Receiver for background upload completion notifications.
    pub upload_rx: std::sync::mpsc::Receiver<UploadComplete>,
    /// Sender for background upload threads to notify completion.
    pub upload_tx: std::sync::mpsc::Sender<UploadComplete>,
    /// Shared coordinator for IPNS publish sequencing and per-folder locking.
    pub publish_coordinator: Arc<PublishCoordinator>,
    /// Debounced publish queue: folders needing metadata publish after mutations.
    /// Publishes are coalesced and deferred until uploads settle.
    publish_queue: HashMap<u64, PublishQueueEntry>,
}

#[cfg(any(feature = "fuse", feature = "winfsp"))]
impl CipherBoxFS {
    /// Get the decrypted folder key for a folder/root inode.
    /// Returns None if the inode is not a folder or root.
    pub fn get_folder_key(&self, folder_ino: u64) -> Option<Vec<u8>> {
        self.inodes.get(folder_ino).and_then(|inode| {
            match &inode.kind {
                inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
                inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
                _ => None,
            }
        })
    }

    /// Build a FolderMetadata struct from the current inode tree (CPU-only, no network I/O).
    /// Returns (metadata, folder_key, ipns_private_key, ipns_name, old_metadata_cid).
    pub fn build_folder_metadata(
        &self,
        folder_ino: u64,
    ) -> Result<
        (
            crate::crypto::folder::FolderMetadata,
            Vec<u8>,
            Vec<u8>,
            String,
            Option<String>,
        ),
        String,
    > {
        let (folder_key, ipns_private_key, ipns_name, child_inos) = {
            let inode = self
                .inodes
                .get(folder_ino)
                .ok_or_else(|| format!("Folder inode {} not found", folder_ino))?;

            let children = inode.children.clone().unwrap_or_default();

            match &inode.kind {
                inode::InodeKind::Root {
                    ipns_private_key,
                    ipns_name,
                } => {
                    let key = ipns_private_key
                        .as_ref()
                        .ok_or("Root folder IPNS private key not available")?
                        .to_vec();
                    let name = ipns_name
                        .as_ref()
                        .ok_or("Root folder IPNS name not available")?
                        .clone();
                    (self.root_folder_key.to_vec(), key, name, children)
                }
                inode::InodeKind::Folder {
                    folder_key,
                    ipns_private_key,
                    ipns_name,
                    ..
                } => {
                    let key = ipns_private_key
                        .as_ref()
                        .ok_or("Subfolder IPNS private key not available")?
                        .to_vec();
                    (folder_key.to_vec(), key, ipns_name.clone(), children)
                }
                _ => return Err("Cannot update metadata for non-folder inode".to_string()),
            }
        };

        let mut metadata_children = Vec::new();
        for &child_ino in &child_inos {
            let child = self
                .inodes
                .get(child_ino)
                .ok_or_else(|| format!("Child inode {} not found", child_ino))?;

            match &child.kind {
                inode::InodeKind::Folder {
                    ipns_name: child_ipns_name,
                    encrypted_folder_key,
                    ipns_private_key: child_ipns_key,
                    ..
                } => {
                    let ipns_key_encrypted = if let Some(key) = child_ipns_key {
                        let wrapped = crate::crypto::ecies::wrap_key(key, &self.public_key)
                            .map_err(|e| format!("Failed to wrap IPNS key: {}", e))?;
                        hex::encode(&wrapped)
                    } else {
                        String::new()
                    };

                    let now_ms = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;
                    let created_ms = child
                        .attr
                        .crtime
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;
                    let modified_ms = child
                        .attr
                        .mtime
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;

                    metadata_children.push(crate::crypto::folder::FolderChild::Folder(
                        crate::crypto::folder::FolderEntry {
                            id: uuid_from_ino(child_ino),
                            name: child.name.clone(),
                            ipns_name: child_ipns_name.clone(),
                            folder_key_encrypted: encrypted_folder_key.clone(),
                            ipns_private_key_encrypted: ipns_key_encrypted,
                            created_at: if created_ms > 0 { created_ms } else { now_ms },
                            modified_at: if modified_ms > 0 { modified_ms } else { now_ms },
                        },
                    ));
                }
                inode::InodeKind::File {
                    file_meta_ipns_name,
                    file_ipns_private_key,
                    file_ipns_key_encrypted_hex,
                    ..
                } => {
                    let now_ms = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;
                    let created_ms = child
                        .attr
                        .crtime
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;
                    let modified_ms = child
                        .attr
                        .mtime
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;

                    // FilePointer IPNS name is required for v2 metadata.
                    // create() generates a random IPNS keypair, so this should always be Some.
                    let ipns_name = match file_meta_ipns_name {
                        Some(name) if !name.is_empty() => name.clone(),
                        _ => {
                            log::error!(
                                "File '{}' (ino {}) has no fileMetaIpnsName -- this should not happen (create() generates IPNS keypair). Skipping file.",
                                child.name, child_ino
                            );
                            continue;
                        }
                    };

                    // Use cached ECIES-wrapped hex if available; only re-wrap if cache is empty
                    let ipns_key_encrypted = if let Some(hex) = file_ipns_key_encrypted_hex {
                        Some(hex.clone())
                    } else if let Some(key) = file_ipns_private_key {
                        match crate::crypto::ecies::wrap_key(key, &self.public_key) {
                            Ok(wrapped) => Some(hex::encode(&wrapped)),
                            Err(e) => {
                                log::warn!(
                                    "File '{}' (ino {}): failed to wrap IPNS key: {}. Omitting ipnsPrivateKeyEncrypted.",
                                    child.name, child_ino, e
                                );
                                None
                            }
                        }
                    } else {
                        None
                    };

                    metadata_children.push(crate::crypto::folder::FolderChild::File(
                        crate::crypto::folder::FilePointer {
                            id: uuid_from_ino(child_ino),
                            name: child.name.clone(),
                            file_meta_ipns_name: ipns_name,
                            ipns_private_key_encrypted: ipns_key_encrypted,
                            created_at: if created_ms > 0 { created_ms } else { now_ms },
                            modified_at: if modified_ms > 0 { modified_ms } else { now_ms },
                        },
                    ));
                }
                _ => {}
            }
        }

        let metadata = crate::crypto::folder::FolderMetadata {
            version: "v2".to_string(),
            children: metadata_children,
        };

        let old_cid = self.metadata_cache.get(&ipns_name).map(|c| c.cid.clone());

        Ok((metadata, folder_key, ipns_private_key, ipns_name, old_cid))
    }

    /// Publish folder metadata immediately (no debounce).
    /// Used for non-upload mutations (unlink, rmdir, rename) where the inode tree
    /// is already in its final state and we want the IPNS record updated ASAP.
    pub fn update_folder_metadata(&mut self, folder_ino: u64) -> Result<(), String> {
        // Mark folder as locally mutated to prevent background refreshes
        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
        // Build metadata and publish immediately (no debounce needed)
        let (metadata, folder_key, ipns_private_key, ipns_name, old_cid) =
            self.build_folder_metadata(folder_ino)?;
        spawn_metadata_publish(
            self.api.clone(),
            self.rt.clone(),
            metadata,
            folder_key,
            ipns_private_key,
            ipns_name,
            old_cid,
            self.publish_coordinator.clone(),
        );
        Ok(())
    }

    /// Drain completed upload notifications and update inode CIDs + caches.
    /// Also flushes the debounced publish queue when uploads settle.
    pub fn drain_upload_completions(&mut self) {
        while let Ok(result) = self.upload_rx.try_recv() {
            log::debug!(
                "Upload complete: ino {} -> CID {}",
                result.ino,
                result.new_cid
            );
            // Update inode CID — only if write_generation matches.
            // This prevents stale uploads from overwriting newer content state
            // (e.g., TC01 upload completing after TC02 has truncated+rewritten).
            if let Some(inode) = self.inodes.get_mut(result.ino) {
                if inode.write_generation == result.write_generation {
                    if let inode::InodeKind::File { ref mut cid, .. } = inode.kind {
                        *cid = result.new_cid.clone();
                    }
                } else {
                    log::debug!(
                        "Skipping stale upload for ino {} (gen {} != current {})",
                        result.ino, result.write_generation, inode.write_generation
                    );
                }
            }
            // Move plaintext from pending_content to content_cache
            if let Some(plaintext) = self.pending_content.remove(&result.ino) {
                self.content_cache.set(&result.new_cid, plaintext);
            }
            // Old file CID is now preserved as a version entry -- do NOT unpin it.
            // Only unpin CIDs from pruned versions that exceeded MAX_VERSIONS_PER_FILE.
            for pruned_cid in &result.pruned_cids {
                let api = self.api.clone();
                let cid = pruned_cid.clone();
                self.rt.spawn(async move {
                    let _ = crate::api::ipfs::unpin_content(&api, &cid).await;
                });
            }
            // Decrement pending upload count for this folder
            if let Some(entry) = self.publish_queue.get_mut(&result.parent_ino) {
                entry.pending_uploads = entry.pending_uploads.saturating_sub(1);
            }
        }
        // Flush any publish queue entries that are ready
        self.flush_publish_queue();
    }

    /// Queue a folder for debounced metadata publish.
    /// Called after mutations (create, unlink, rmdir, rename) that change folder contents.
    pub fn queue_publish(&mut self, folder_ino: u64, has_pending_upload: bool) {
        let entry = self.publish_queue.entry(folder_ino).or_insert(PublishQueueEntry {
            first_dirty: std::time::Instant::now(),
            pending_uploads: 0,
        });
        if has_pending_upload {
            entry.pending_uploads += 1;
        }
        // Mark folder as locally mutated to prevent background refreshes
        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
    }

    /// Flush publish queue entries that are ready.
    /// Criteria: all uploads complete AND debounce period elapsed (1.5s),
    /// OR safety valve: 10s since first change regardless of pending uploads.
    fn flush_publish_queue(&mut self) {
        let now = std::time::Instant::now();
        let debounce = std::time::Duration::from_millis(1500);
        let safety_valve = std::time::Duration::from_secs(10);

        // Collect folders ready to publish
        let ready: Vec<u64> = self.publish_queue.iter()
            .filter(|(_, entry)| {
                let elapsed = now.duration_since(entry.first_dirty);
                if elapsed >= safety_valve {
                    // Safety valve: force publish regardless of pending uploads
                    if entry.pending_uploads > 0 {
                        log::warn!(
                            "Publish safety valve triggered with {} pending upload(s)",
                            entry.pending_uploads
                        );
                    }
                    return true;
                }
                entry.pending_uploads == 0 && elapsed >= debounce
            })
            .map(|(&ino, _)| ino)
            .collect();

        for folder_ino in ready {
            self.publish_queue.remove(&folder_ino);
            match self.build_folder_metadata(folder_ino) {
                Ok((metadata, folder_key, ipns_private_key, ipns_name, old_cid)) => {
                    spawn_metadata_publish(
                        self.api.clone(),
                        self.rt.clone(),
                        metadata,
                        folder_key,
                        ipns_private_key,
                        ipns_name,
                        old_cid,
                        self.publish_coordinator.clone(),
                    );
                }
                Err(e) => {
                    log::error!("Failed to build folder metadata for publish (ino {}): {}", folder_ino, e);
                }
            }
        }
    }

    /// Drain background folder refresh results (non-blocking).
    /// Called from lookup() and readdir() to apply results from async folder fetches.
    /// Skips refreshes for folders with recent local mutations (prevents stale
    /// remote metadata from overwriting local changes before IPNS publish propagates).
    pub fn drain_refresh_completions(&mut self) {
        // Clean up expired mutation cooldowns (>30s old)
        let cutoff = std::time::Instant::now() - std::time::Duration::from_secs(30);
        self.mutated_folders.retain(|_, ts| *ts > cutoff);

        while let Ok(refresh) = self.refresh_rx.try_recv() {
            // Skip stale refreshes for recently-mutated folders or folders
            // with pending publishes (to prevent re-adding deleted/stale children)
            if self.mutated_folders.contains_key(&refresh.ino)
                || self.publish_queue.contains_key(&refresh.ino)
            {
                log::debug!(
                    "refresh skipped for ino {} (locally mutated or publish pending)",
                    refresh.ino
                );
                // Still update cache so readdir doesn't re-fire refreshes
                self.metadata_cache.set(&refresh.ipns_name, refresh.metadata.clone(), refresh.cid);
                continue;
            }

            self.metadata_cache.set(&refresh.ipns_name, refresh.metadata.clone(), refresh.cid.clone());
            // Background refresh: merge_only=true to preserve locally-created files
            // that haven't been published to IPNS yet.
            if let Err(e) = self.inodes.populate_folder(
                refresh.ino, &refresh.metadata, &self.private_key, &self.public_key, true,
            ) {
                log::warn!("Drain refresh apply failed for ino {}: {}", refresh.ino, e);
            }

            // Resolve FilePointers eagerly after populating.
            // TODO: This blocks the filesystem thread with O(N * timeout) latency for N
            // unresolved FilePointers. Should be refactored to spawn async tasks via
            // a file_pointer_tx/rx channel pair (like refresh_tx/rx) to avoid stalling
            // the single NFS thread on network I/O.
            let unresolved = self.inodes.get_unresolved_file_pointers();
            if !unresolved.is_empty() {
                // Get folder key for FilePointer resolution
                let folder_key = match self.inodes.get(refresh.ino) {
                    Some(inode) => match &inode.kind {
                        inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
                        inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
                        _ => None,
                    },
                    None => None,
                };
                if let Some(fk) = folder_key {
                    let api = self.api.clone();
                    let rt = self.rt.clone();
                    for (ino, ipns_name) in &unresolved {
                        let fk_arr: Result<[u8; 32], _> = fk.as_slice().try_into();
                        if let Ok(fk_arr) = fk_arr {
                            let resolve_result = block_with_timeout(&rt, async {
                                let resp = crate::api::ipns::resolve_ipns(&api, ipns_name).await?;
                                let bytes = crate::api::ipfs::fetch_content(&api, &resp.cid).await?;
                                Ok::<Vec<u8>, String>(bytes)
                            });
                            match resolve_result {
                                Ok(enc_bytes) => {
                                    match decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &fk_arr) {
                                        Ok(fm) => {
                                            self.inodes.resolve_file_pointer(
                                                *ino, fm.cid, fm.file_key_encrypted,
                                                fm.file_iv, fm.size, fm.encryption_mode,
                                                fm.versions,
                                            );
                                        }
                                        Err(e) => log::warn!("Drain FilePointer decrypt failed for ino {}: {}", ino, e),
                                    }
                                }
                                Err(e) => log::warn!("Drain FilePointer resolve failed for ino {}: {}", ino, e),
                            }
                        }
                    }
                }
            }
        }
    }

    /// Drain background content prefetch results into the content cache (non-blocking).
    /// Called from read() and open() to apply results from async IPFS fetches.
    pub fn drain_content_prefetches(&mut self) {
        while let Ok(msg) = self.content_rx.try_recv() {
            match msg {
                PendingContent::Success { cid, data } => {
                    self.prefetching.remove(&cid);
                    self.content_cache.set(&cid, data);
                }
                PendingContent::Failure { cid } => {
                    self.prefetching.remove(&cid);
                }
            }
        }
    }
}

/// Generate a UUID-like string from an inode number (deterministic).
/// Used for folder/file IDs in metadata when we don't have the original UUID.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
fn uuid_from_ino(ino: u64) -> String {
    format!(
        "{:08x}-{:04x}-4{:03x}-{:04x}-{:012x}",
        (ino >> 32) as u32,
        ((ino >> 16) & 0xFFFF) as u16,
        (ino & 0xFFF) as u16,
        (0x8000 | (ino & 0x3FFF)) as u16,
        ino & 0xFFFFFFFFFFFF,
    )
}

/// Get the mount point path: ~/CipherBox
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub fn mount_point() -> PathBuf {
    dirs::home_dir()
        .expect("Could not determine home directory")
        .join("CipherBox")
}

/// Mount the FUSE filesystem after successful authentication (macOS only).
///
/// Creates the ~/CipherBox directory if it doesn't exist, builds the
/// CipherBoxFS with keys from AppState, and spawns the FUSE event loop
/// on a dedicated std::thread (not tokio -- fuser runs its own event loop).
///
/// Returns a JoinHandle for the mount thread.
#[cfg(feature = "fuse")]
pub async fn mount_filesystem(
    state: &AppState,
    rt: tokio::runtime::Handle,
    private_key: Vec<u8>,
    public_key: Vec<u8>,
    root_folder_key: Vec<u8>,
    root_ipns_name: String,
    root_ipns_private_key: Option<Vec<u8>>,
    tee_public_key: Option<Vec<u8>>,
    tee_key_epoch: Option<u32>,
) -> Result<std::thread::JoinHandle<()>, String> {
    let mount_path = mount_point();

    // Refuse to proceed if mount point is a symlink (TOCTOU defense)
    if mount_path.is_symlink() {
        return Err("Mount point is a symlink — refusing to proceed".to_string());
    }

    // Create mount directory if it doesn't exist
    if !mount_path.exists() {
        std::fs::create_dir_all(&mount_path)
            .map_err(|e| format!("Failed to create mount point: {}", e))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(&mount_path, std::fs::Permissions::from_mode(0o700));
        }
    } else {
        // Clean stale files left after a crash (e.g. .DS_Store, .metadata_never_index).
        // FUSE mount will fail or behave unexpectedly if the directory isn't empty.
        if let Ok(entries) = std::fs::read_dir(&mount_path) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    let _ = std::fs::remove_dir_all(&path);
                } else {
                    let _ = std::fs::remove_file(&path);
                }
            }
            log::info!("Cleaned stale mount point: {}", mount_path.display());
        }
    }

    // Prevent Spotlight from indexing the mount (macOS only)
    #[cfg(target_os = "macos")]
    {
        let never_index = mount_path.join(".metadata_never_index");
        if !never_index.exists() {
            let _ = std::fs::File::create(&never_index);
        }
    }

    // Create temp directory for write buffering
    let temp_dir = std::env::temp_dir().join("cipherbox");
    std::fs::create_dir_all(&temp_dir)
        .map_err(|e| format!("Failed to create temp directory: {}", e))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&temp_dir, std::fs::Permissions::from_mode(0o700));
    }

    // Build the filesystem
    let mut inodes = inode::InodeTable::new();

    // Set root inode's IPNS data
    if let Some(root) = inodes.get_mut(inode::ROOT_INO) {
        root.kind = inode::InodeKind::Root {
            ipns_private_key: root_ipns_private_key.map(Zeroizing::new),
            ipns_name: Some(root_ipns_name.clone()),
        };
    }

    // Channels for background operations
    let (refresh_tx, refresh_rx) = std::sync::mpsc::channel::<PendingRefresh>();
    let (content_tx, content_rx) = std::sync::mpsc::channel::<PendingContent>();
    let (upload_tx, upload_rx) = std::sync::mpsc::channel::<UploadComplete>();

    // Pre-populate root folder BEFORE mounting so init()/readdir() have no network I/O.
    // This runs on the calling thread (tokio context available via rt handle).
    let mut metadata_cache = cache::MetadataCache::new();
    log::info!("Pre-populating root folder from IPNS...");
    let fetch_result: Result<(Vec<u8>, String), String> = async {
        let resolve_resp =
            crate::api::ipns::resolve_ipns(&state.api, &root_ipns_name).await?;
        let encrypted_bytes =
            crate::api::ipfs::fetch_content(&state.api, &resolve_resp.cid).await?;
        Ok((encrypted_bytes, resolve_resp.cid))
    }.await;
    match fetch_result {
        Ok((encrypted_bytes, cid)) => {
            match decrypt::decrypt_metadata_from_ipfs_public(&encrypted_bytes, &root_folder_key) {
                Ok(metadata) => {
                    // Cache metadata directly for readdir staleness checks
                    metadata_cache.set(&root_ipns_name, metadata.clone(), cid);

                    // Populate inode table -- initial mount, full replace
                    match inodes.populate_folder(inode::ROOT_INO, &metadata, &private_key, &public_key, false) {
                        Ok(()) => {
                            log::info!("Root folder pre-populated successfully");

                            // Resolve FilePointers eagerly before mount
                            let unresolved = inodes.get_unresolved_file_pointers();
                            if !unresolved.is_empty() {
                                log::info!("Resolving {} root FilePointer(s)...", unresolved.len());
                                let root_folder_key_arr: Result<[u8; 32], _> = root_folder_key.as_slice().try_into();
                                if let Ok(fk) = root_folder_key_arr {
                                    for (fp_ino, fp_ipns) in &unresolved {
                                        let fp_result: Result<Vec<u8>, String> = async {
                                            let resp = crate::api::ipns::resolve_ipns(&state.api, fp_ipns).await?;
                                            let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
                                            Ok(bytes)
                                        }.await;
                                        match fp_result {
                                            Ok(enc_bytes) => {
                                                match decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &fk) {
                                                    Ok(fm) => {
                                                        inodes.resolve_file_pointer(
                                                            *fp_ino, fm.cid, fm.file_key_encrypted,
                                                            fm.file_iv, fm.size, fm.encryption_mode,
                                                            fm.versions,
                                                        );
                                                    }
                                                    Err(e) => log::warn!("Root FilePointer decrypt failed for ino {}: {}", fp_ino, e),
                                                }
                                            }
                                            Err(e) => log::warn!("Root FilePointer resolve failed for ino {}: {}", fp_ino, e),
                                        }
                                    }
                                }
                            }
                        }
                        Err(e) => log::warn!("Root folder populate failed: {}", e),
                    }

                    // Pre-populate immediate subfolders so Finder's first READDIR
                    // returns correct data. NFS clients cache READDIR aggressively
                    // and won't re-fetch even when mtime changes, so returning empty
                    // on first access causes permanently stale Finder listings.
                    let subfolder_infos: Vec<(u64, String, Zeroizing<Vec<u8>>)> = inodes
                        .inodes
                        .values()
                        .filter_map(|inode| {
                            if inode.parent_ino != inode::ROOT_INO { return None; }
                            if let inode::InodeKind::Folder { ref ipns_name, ref folder_key, .. } = inode.kind {
                                Some((inode.ino, ipns_name.clone(), folder_key.clone()))
                            } else {
                                None
                            }
                        })
                        .collect();

                    for (sub_ino, sub_ipns, sub_key) in &subfolder_infos {
                        log::info!("Pre-populating subfolder ino={} ipns={}", sub_ino, sub_ipns);
                        let sub_result: Result<(Vec<u8>, String), String> = async {
                            let resp = crate::api::ipns::resolve_ipns(&state.api, sub_ipns).await?;
                            let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
                            Ok((bytes, resp.cid))
                        }.await;
                        match sub_result {
                            Ok((enc_bytes, sub_cid)) => {
                                match decrypt::decrypt_metadata_from_ipfs_public(&enc_bytes, sub_key) {
                                    Ok(sub_metadata) => {
                                        metadata_cache.set(sub_ipns, sub_metadata.clone(), sub_cid);
                                        match inodes.populate_folder(*sub_ino, &sub_metadata, &private_key, &public_key, false) {
                                            Ok(()) => {
                                                log::info!("Subfolder ino={} pre-populated", sub_ino);
                                                // Resolve FilePointers in subfolder
                                                let sub_unresolved = inodes.get_unresolved_file_pointers();
                                                if !sub_unresolved.is_empty() {
                                                    let sk_arr: Result<[u8; 32], _> = sub_key.as_slice().try_into();
                                                    if let Ok(sk) = sk_arr {
                                                        for (fp_ino, fp_ipns) in &sub_unresolved {
                                                            let fp_result: Result<Vec<u8>, String> = async {
                                                                let resp = crate::api::ipns::resolve_ipns(&state.api, fp_ipns).await?;
                                                                let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
                                                                Ok(bytes)
                                                            }.await;
                                                            match fp_result {
                                                                Ok(enc_bytes) => {
                                                                    match decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &sk) {
                                                                        Ok(fm) => {
                                                                            inodes.resolve_file_pointer(
                                                                                *fp_ino, fm.cid, fm.file_key_encrypted,
                                                                                fm.file_iv, fm.size, fm.encryption_mode,
                                                                                fm.versions,
                                                                            );
                                                                        }
                                                                        Err(e) => log::warn!("Sub FilePointer decrypt failed: {}", e),
                                                                    }
                                                                }
                                                                Err(e) => log::warn!("Sub FilePointer resolve failed: {}", e),
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                            Err(e) => log::warn!("Subfolder ino={} populate failed: {}", sub_ino, e),
                                        }
                                    }
                                    Err(e) => log::warn!("Subfolder ino={} decrypt failed: {}", sub_ino, e),
                                }
                            }
                            Err(e) => log::warn!("Subfolder ino={} fetch failed: {}", sub_ino, e),
                        }
                    }
                }
                Err(e) => log::warn!("Root metadata decryption failed: {}", e),
            }
        }
        Err(e) => log::warn!("Root folder fetch failed (mount will show empty): {}", e),
    }

    let fs = CipherBoxFS {
        inodes,
        metadata_cache,
        content_cache: cache::ContentCache::new(),
        api: state.api.clone(),
        private_key: Zeroizing::new(private_key),
        public_key: Zeroizing::new(public_key),
        root_folder_key: Zeroizing::new(root_folder_key),
        root_ipns_name,
        rt,
        next_fh: AtomicU64::new(1),
        open_files: HashMap::new(),
        temp_dir,
        tee_public_key,
        tee_key_epoch,
        refresh_rx,
        refresh_tx,
        prefetching: std::collections::HashSet::new(),
        content_rx,
        content_tx,
        pending_content: HashMap::new(),
        upload_rx,
        upload_tx,
        mutated_folders: HashMap::new(),
        publish_coordinator: Arc::new(PublishCoordinator::new()),
        publish_queue: HashMap::new(),
    };

    let mount_path_clone = mount_path.clone();

    // Mount options — platform-specific.
    // Linux: kernel FUSE supports AutoUnmount and DefaultPermissions natively.
    // macOS: FUSE-T (NFS/SMB proxy) requires custom options; AutoUnmount and
    // DefaultPermissions are not supported.
    // Linux: kernel FUSE with libfuse3. We skip AutoUnmount because it
    // requires allow_other/allow_root, which in turn needs user_allow_other
    // in /etc/fuse.conf — an extra config step we don't want to impose.
    // Instead, unmount_filesystem() calls fusermount3 -u directly.
    #[cfg(target_os = "linux")]
    let options = vec![
        MountOption::FSName("CipherBox".to_string()),
        MountOption::DefaultPermissions,
        MountOption::RW,
    ];

    #[cfg(target_os = "macos")]
    let options = vec![
        // FUSE-T mount options:
        // - backend=smb: Use SMB instead of NFS backend. NFS has a known macOS kernel
        //   bug where WRITE RPCs never reach the FUSE-T server for newly created files,
        //   causing permanent process hangs. SMB backend avoids this entirely.
        MountOption::FSName("CipherBox".to_string()),
        MountOption::CUSTOM("volname=CipherBox".to_string()),
        MountOption::CUSTOM("noappledouble".to_string()),
        MountOption::CUSTOM("noapplexattr".to_string()),
        MountOption::CUSTOM("backend=smb".to_string()),
        MountOption::RW,
    ];

    // Spawn FUSE event loop on a dedicated OS thread (not tokio).
    // Use a channel so the thread can signal back if mount2 fails immediately
    // (e.g. macFUSE kext not loaded). If mount2 succeeds, it blocks until
    // unmount and never sends on the channel, so we use a recv_timeout.
    let (tx, rx) = std::sync::mpsc::sync_channel::<Result<(), String>>(1);

    let handle = std::thread::Builder::new()
        .name("fuse-mount".to_string())
        .spawn(move || {
            log::info!(
                "Mounting CipherBoxFS at {}",
                mount_path_clone.display()
            );
            match fuser::mount2(fs, &mount_path_clone, &options) {
                Ok(()) => {
                    log::info!("FUSE filesystem unmounted cleanly");
                    let _ = tx.send(Ok(()));
                }
                Err(e) => {
                    log::error!("FUSE mount error: {}", e);
                    let _ = tx.send(Err(format!("FUSE mount error: {}", e)));
                }
            }
        })
        .map_err(|e| format!("Failed to spawn FUSE thread: {}", e))?;

    // Wait up to 2 seconds for the mount to either fail or stabilize.
    // If mount2 fails (e.g. missing kext), the error arrives quickly.
    // If mount2 succeeds, it blocks (running the event loop) and we get a timeout.
    match rx.recv_timeout(std::time::Duration::from_secs(2)) {
        Ok(Ok(())) => {
            // Filesystem was unmounted immediately (unusual)
            Err("FUSE filesystem unmounted immediately after mounting".to_string())
        }
        Ok(Err(e)) => {
            // Mount failed — propagate the error
            Err(e)
        }
        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
            // No response after 2s — mount is running
            log::info!("FUSE mount confirmed at {}", mount_path.display());
            Ok(handle)
        }
        Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
            Err("FUSE mount thread exited unexpectedly".to_string())
        }
    }
}

/// Unmount the FUSE filesystem (macOS only).
///
/// Calls the system `umount` command to cleanly unmount ~/CipherBox.
#[cfg(all(feature = "fuse", target_os = "macos"))]
pub fn unmount_filesystem() -> Result<(), String> {
    let mount_path = mount_point();
    log::info!("Unmounting CipherBoxFS at {}", mount_path.display());

    // Clean up temp directory
    let temp_dir = std::env::temp_dir().join("cipherbox");
    if temp_dir.exists() {
        if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
            log::warn!("Failed to clean temp directory: {}", e);
        }
    }

    let status = std::process::Command::new("umount")
        .arg(mount_path.to_str().unwrap())
        .status()
        .map_err(|e| format!("Failed to run umount: {}", e))?;

    if status.success() {
        log::info!("FUSE filesystem unmounted successfully");
        Ok(())
    } else {
        // Try diskutil unmount force as fallback on macOS — Finder keeps handles open
        log::info!("umount failed (likely busy), trying diskutil unmount force");
        let status = std::process::Command::new("diskutil")
            .args(["unmount", "force", mount_path.to_str().unwrap()])
            .status()
            .map_err(|e| format!("Failed to run diskutil unmount force: {}", e))?;

        if status.success() {
            log::info!("FUSE filesystem force-unmounted via diskutil");
            Ok(())
        } else {
            Err(format!(
                "Failed to unmount {} — close Finder windows and retry",
                mount_path.display()
            ))
        }
    }
}

/// Unmount the FUSE filesystem (Linux only).
///
/// Tries fusermount3 -u first (preferred, no root needed), then fusermount -u
/// (FUSE 2 compat), then umount as last resort (may need privileges).
#[cfg(all(feature = "fuse", target_os = "linux"))]
pub fn unmount_filesystem() -> Result<(), String> {
    let mount_path = mount_point();
    log::info!("Unmounting CipherBoxFS at {}", mount_path.display());

    // Clean up temp directory
    let temp_dir = std::env::temp_dir().join("cipherbox");
    if temp_dir.exists() {
        if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
            log::warn!("Failed to clean temp directory: {}", e);
        }
    }

    let mount_str = mount_path.to_str().unwrap();

    // Try fusermount3 first (preferred, doesn't require root)
    let status = std::process::Command::new("fusermount3")
        .args(["-u", mount_str])
        .status();

    match status {
        Ok(s) if s.success() => {
            log::info!("FUSE filesystem unmounted via fusermount3");
            return Ok(());
        }
        _ => {
            log::info!("fusermount3 failed, trying fusermount (FUSE 2 compat)");
        }
    }

    // Fallback to fusermount (FUSE 2 compat)
    let status = std::process::Command::new("fusermount")
        .args(["-u", mount_str])
        .status();

    match status {
        Ok(s) if s.success() => {
            log::info!("FUSE filesystem unmounted via fusermount");
            return Ok(());
        }
        _ => {
            log::info!("fusermount failed, trying umount (may need privileges)");
        }
    }

    // Last resort: umount (may require privileges)
    let status = std::process::Command::new("umount")
        .arg(mount_str)
        .status()
        .map_err(|e| format!("Failed to run umount: {}", e))?;

    if status.success() {
        log::info!("FUSE filesystem unmounted via umount");
        Ok(())
    } else {
        Err(format!(
            "Failed to unmount {} — close file managers and retry",
            mount_path.display()
        ))
    }
}

#[cfg(test)]
#[cfg(any(feature = "fuse", feature = "winfsp"))]
mod tests {
    use super::merge_folder_children;
    use crate::crypto::folder::{FilePointer, FolderChild, FolderEntry, FolderMetadata};

    // ── Helpers ───────────────────────────────────────────────────────────

    fn make_folder(ipns: &str, name: &str) -> FolderChild {
        FolderChild::Folder(FolderEntry {
            id: format!("id-{}", name),
            name: name.to_string(),
            ipns_name: ipns.to_string(),
            folder_key_encrypted: "encrypted-key".to_string(),
            ipns_private_key_encrypted: "encrypted-ipns-key".to_string(),
            created_at: 1000,
            modified_at: 2000,
        })
    }

    fn make_file(ipns: &str, name: &str) -> FolderChild {
        FolderChild::File(FilePointer {
            id: format!("id-{}", name),
            name: name.to_string(),
            file_meta_ipns_name: ipns.to_string(),
            ipns_private_key_encrypted: None,
            created_at: 1000,
            modified_at: 2000,
        })
    }

    fn metadata(children: Vec<FolderChild>) -> FolderMetadata {
        FolderMetadata {
            version: "v2".to_string(),
            children,
        }
    }

    fn child_ipns(child: &FolderChild) -> &str {
        match child {
            FolderChild::Folder(f) => &f.ipns_name,
            FolderChild::File(f) => &f.file_meta_ipns_name,
        }
    }

    fn child_name(child: &FolderChild) -> &str {
        match child {
            FolderChild::Folder(f) => &f.name,
            FolderChild::File(f) => &f.name,
        }
    }

    // ── merge_folder_children tests ──────────────────────────────────────

    #[test]
    fn merge_both_empty() {
        let local = metadata(vec![]);
        let remote = metadata(vec![]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.version, "v2");
        assert!(merged.children.is_empty());
    }

    #[test]
    fn merge_local_empty_preserves_remote() {
        let local = metadata(vec![]);
        let remote = metadata(vec![
            make_file("ipns-a", "photo.jpg"),
            make_folder("ipns-b", "docs"),
        ]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 2);
        assert_eq!(child_ipns(&merged.children[0]), "ipns-a");
        assert_eq!(child_ipns(&merged.children[1]), "ipns-b");
    }

    #[test]
    fn merge_remote_empty_preserves_local() {
        let local = metadata(vec![
            make_file("ipns-a", "photo.jpg"),
            make_folder("ipns-b", "docs"),
        ]);
        let remote = metadata(vec![]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 2);
        assert_eq!(child_ipns(&merged.children[0]), "ipns-a");
        assert_eq!(child_ipns(&merged.children[1]), "ipns-b");
    }

    #[test]
    fn merge_identical_children_uses_local_version() {
        let local = metadata(vec![make_file("ipns-a", "local-name.jpg")]);
        let remote = metadata(vec![make_file("ipns-a", "remote-name.jpg")]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 1);
        // Local version wins (handles rename)
        assert_eq!(child_name(&merged.children[0]), "local-name.jpg");
    }

    #[test]
    fn merge_local_rename_overwrites_remote() {
        // Same IPNS name, different display name = rename on local device
        let local = metadata(vec![make_folder("ipns-x", "renamed-folder")]);
        let remote = metadata(vec![make_folder("ipns-x", "original-folder")]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 1);
        assert_eq!(child_name(&merged.children[0]), "renamed-folder");
    }

    #[test]
    fn merge_disjoint_children_union() {
        // Local added file-a, remote added file-b => merged has both
        let local = metadata(vec![make_file("ipns-a", "file-a.txt")]);
        let remote = metadata(vec![make_file("ipns-b", "file-b.txt")]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 2);
        let ipns_set: Vec<&str> = merged.children.iter().map(child_ipns).collect();
        assert!(ipns_set.contains(&"ipns-a"));
        assert!(ipns_set.contains(&"ipns-b"));
    }

    #[test]
    fn merge_preserves_remote_only_children_no_deletion() {
        // Local has [A, B], remote has [A, B, C].
        // C is absent from local but MUST be preserved (additive merge).
        let local = metadata(vec![
            make_file("ipns-a", "a.txt"),
            make_file("ipns-b", "b.txt"),
        ]);
        let remote = metadata(vec![
            make_file("ipns-a", "a.txt"),
            make_file("ipns-b", "b.txt"),
            make_file("ipns-c", "c.txt"),
        ]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 3);
        let ipns_set: Vec<&str> = merged.children.iter().map(child_ipns).collect();
        assert!(ipns_set.contains(&"ipns-c"), "remote-only child must be preserved");
    }

    #[test]
    fn merge_concurrent_additions_from_both_devices() {
        // Both devices started from [A], local added B, remote added C.
        let local = metadata(vec![
            make_file("ipns-a", "a.txt"),
            make_file("ipns-b", "b-from-local.txt"),
        ]);
        let remote = metadata(vec![
            make_file("ipns-a", "a.txt"),
            make_file("ipns-c", "c-from-remote.txt"),
        ]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 3);
        let ipns_set: Vec<&str> = merged.children.iter().map(child_ipns).collect();
        assert!(ipns_set.contains(&"ipns-a"));
        assert!(ipns_set.contains(&"ipns-b"));
        assert!(ipns_set.contains(&"ipns-c"));
    }

    #[test]
    fn merge_mixed_folders_and_files() {
        let local = metadata(vec![
            make_folder("ipns-dir", "my-folder"),
            make_file("ipns-file-1", "readme.md"),
        ]);
        let remote = metadata(vec![
            make_folder("ipns-dir", "my-folder"),
            make_file("ipns-file-2", "notes.txt"),
        ]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 3);
        let ipns_set: Vec<&str> = merged.children.iter().map(child_ipns).collect();
        assert!(ipns_set.contains(&"ipns-dir"));
        assert!(ipns_set.contains(&"ipns-file-1"));
        assert!(ipns_set.contains(&"ipns-file-2"));
    }

    #[test]
    fn merge_preserves_remote_order_then_appends_local() {
        // Merged output should list remote children first (in remote order),
        // then local-only additions at the end.
        let local = metadata(vec![
            make_file("ipns-c", "c.txt"),
            make_file("ipns-a", "a.txt"),
        ]);
        let remote = metadata(vec![
            make_file("ipns-b", "b.txt"),
            make_file("ipns-a", "a.txt"),
        ]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 3);
        // Remote order: B, A; then local-only: C
        assert_eq!(child_ipns(&merged.children[0]), "ipns-b");
        assert_eq!(child_ipns(&merged.children[1]), "ipns-a");
        assert_eq!(child_ipns(&merged.children[2]), "ipns-c");
    }

    #[test]
    fn merge_no_duplicates_when_same_child_in_both() {
        let local = metadata(vec![
            make_file("ipns-a", "a.txt"),
            make_file("ipns-b", "b.txt"),
        ]);
        let remote = metadata(vec![
            make_file("ipns-a", "a.txt"),
            make_file("ipns-b", "b.txt"),
        ]);
        let merged = merge_folder_children(&local, remote);
        assert_eq!(merged.children.len(), 2, "should not produce duplicates");
    }

    #[test]
    fn merge_large_scenario() {
        // Simulate a folder with many children from different devices.
        let mut local_children = Vec::new();
        let mut remote_children = Vec::new();

        // Shared children (0..10)
        for i in 0..10 {
            local_children.push(make_file(&format!("ipns-shared-{}", i), &format!("shared-{}.txt", i)));
            remote_children.push(make_file(&format!("ipns-shared-{}", i), &format!("shared-{}.txt", i)));
        }
        // Local-only children (10..15)
        for i in 10..15 {
            local_children.push(make_file(&format!("ipns-local-{}", i), &format!("local-{}.txt", i)));
        }
        // Remote-only children (15..20)
        for i in 15..20 {
            remote_children.push(make_file(&format!("ipns-remote-{}", i), &format!("remote-{}.txt", i)));
        }

        let local = metadata(local_children);
        let remote = metadata(remote_children);
        let merged = merge_folder_children(&local, remote);

        // 10 shared + 5 local-only + 5 remote-only = 20
        assert_eq!(merged.children.len(), 20);
    }
}

